def main():
 p=argparse.ArgumentParser();p.add_argument('--config',type=Path,required=True);p.add_argument('--runs-root',type=Path,required=True);p.add_argument('--run-id',required=True);a=p.parse_args();c=yaml.safe_load(a.config.read_text());d=a.runs_root/'worldsim_v67'/c['task_id']/a.run_id;d.mkdir(parents=True,exist_ok=False);(d/'resolved.yaml').write_text(yaml.safe_dump(c,sort_keys=False));started=time.monotonic();torch.manual_seed(int(c['seed']));torch.cuda.reset_peak_memory_stats();ens=torch.load(a.runs_root/c['frozen_p126']['run']/c['frozen_p126']['artifact'],map_location='cuda');members=[]
 for state in ens['member_state_dicts']:
  member=DirectionalActorGaussian(20,ens['hidden_dimensions']).cuda();member.load_state_dict(state);members.append(member.eval())
 density,fd=_load_density(a.runs_root/c['frozen_p182']['run']/c['frozen_p182']['artifact']);p199=torch.load(a.runs_root/c['frozen_p199']['run']/c['frozen_p199']['artifact'],map_location='cuda');copula=JointHorizonCopula(8,p199['hidden_dimensions'],4).cuda();copula.load_state_dict(p199['model_state_dict']);copula.eval();p203=torch.load(a.runs_root/c['frozen_p203']['run']/c['frozen_p203']['artifact'],map_location='cuda');calibrator=MonotoneBetaCalibration().cuda();calibrator.load_state_dict(p203['model_state_dict']);calibrator.eval();h=np.asarray(c['horizons_seconds'],np.float32);anchors=np.asarray(c['feature_anchor_budgets'],np.float32);common=(members,ens,density,fd,p199,copula,calibrator,h);tail=(float(c['boundary_state_cost']['clearance_floor_m']),int(c['teacher']['monte_carlo_samples']),int(c['seed']),float(c['teacher']['ignored_future_marginal_probability']));sf,_,_,ss,_=_dataset(a.runs_root/c['source_rows']['run']/c['source_rows']['artifact'],*common,anchors,*tail);f201,_,_,s201,_=_dataset(a.runs_root/c['p201_rows']['run']/c['p201_rows']['artifact'],*common,anchors,*tail);size=int(c['group_size']);sg,sgs=_groups(sf,ss,size);g201,_=_groups(f201,s201,size);surface=torch.load(a.runs_root/c['frozen_p284']['run']/c['frozen_p284']['artifact'],map_location='cuda');teacher=ConformalizedLCBSurface(int(surface['context_width']),int(surface['budget_rate_knot_count']),int(surface['tolerance_rate_knot_count'])).cuda();teacher.load_state_dict(surface['model_state_dict']);teacher.eval();artifact=torch.load(a.runs_root/c['frozen_p285']['run']/c['frozen_p285']['artifact'],map_location='cuda');policy=EpistemicLCBLagrangianPolicy(int(artifact['width']),int(artifact['rate_knot_count'])).cuda();policy.load_state_dict(artifact['model_state_dict']);policy.eval();alphas=np.asarray(c['training_alpha_fairness'],np.float32);ha=np.asarray(c['heldout_alpha_fairness'],np.float32);tolerances=np.asarray(c['training_risk_tolerances'],np.float32);ht=np.asarray(c['heldout_risk_tolerances'],np.float32);td=np.asarray(artifact['risk_tolerance_domain'],np.float32);tol_z=(2*(tolerances-td[0])/(td[1]-td[0])-1).astype(np.float32);htol_z=(2*(ht-td[0])/(td[1]-td[0])-1).astype(np.float32);floors=np.asarray(c['training_final_reliability_floors'],np.float32);hf=np.asarray(c['heldout_final_reliability_floors'],np.float32);fdomain=np.asarray(artifact['floor_domain'],np.float32);floor_z=(2*(floors-fdomain[0])/(fdomain[1]-fdomain[0])-1).astype(np.float32);hfloor_z=(2*(hf-fdomain[0])/(fdomain[1]-fdomain[0])-1).astype(np.float32);fractions=np.asarray(c['training_attainable_budget_fractions'],np.float32);hfractions=np.asarray(c['heldout_attainable_budget_fractions'],np.float32);chunk=int(c['inference_chunk_size']);steps=int(c['teacher_bisection_steps']);source_target,_,_=_target_prices(policy,sg,alphas,tol_z,floor_z,fractions,steps,chunk);target201,low201,high201=_target_prices(policy,g201,ha,htol_z,hfloor_z,hfractions,steps,chunk);dev=sgs%int(c['split']['development_scene_modulus'])==int(c['split']['development_scene_remainder']);source_heldout,source_low,source_high=_target_prices(policy,sg[dev],ha,htol_z,hfloor_z,hfractions,steps,chunk);summary=np.concatenate((sg.mean(1),sg.std(1)),1).astype(np.float32);x=torch.from_numpy(summary).cuda();target=torch.from_numpy(source_target).cuda();fz=torch.from_numpy(2*fractions-1).cuda();at=torch.from_numpy(alphas).cuda();tt=torch.from_numpy(tol_z).cuda();ft=torch.from_numpy(floor_z).cuda();train_idx=torch.from_numpy(np.flatnonzero(~dev)).cuda();m=c['student'];student=EpistemicLCBGroupDual(int(m['width']),int(m['rate_knot_count'])).cuda();opt=torch.optim.AdamW(student.parameters(),lr=float(m['learning_rate']),weight_decay=float(m['weight_decay']));last=0.
 for step in range(int(m['steps'])):
  idx=train_idx[torch.randint(len(train_idx),(int(m['batch_size']),),device='cuda')];ai=torch.randint(len(alphas),(len(idx),),device='cuda');ti=torch.randint(len(tolerances),(len(idx),),device='cuda');li=torch.randint(len(floors),(len(idx),),device='cuda');fi=torch.randint(len(fractions),(len(idx),),device='cuda');prediction=student(x[idx],fz[fi],at[ai],tt[ti],ft[li]);loss=F.l1_loss(prediction,target[idx,ai,ti,li,fi]);opt.zero_grad(set_to_none=True);loss.backward();opt.step();last=float(loss.detach())
  if step%500==0:print(f'P286 additive LCB group dual step={step+1} price_mae={last:.7f}',flush=True)
 mean=float(artifact['shadow_price_log_mean']);scale=float(artifact['shadow_price_log_scale']);epsilon=float(artifact['alpha_utility_epsilon']);penalty=float(artifact['shortfall_penalty']);source=_evaluate(student,policy,teacher,sg[dev],source_heldout,source_low,source_high,ha,htol_z,hf,hfloor_z,hfractions,mean,scale,epsilon,penalty,chunk);r201=_evaluate(student,policy,teacher,g201,target201,low201,high201,ha,htol_z,hf,hfloor_z,hfractions,mean,scale,epsilon,penalty,chunk);decision=c['decision'];checks={'P201_budget_constraint_fidelity':r201['attained_budget_fraction_MAE']<=float(decision['maximum_P201_attained_budget_fraction_MAE']),'P201_additive_LCB_group_regret':r201['mean_frozen_LCB_floor_Lagrangian_group_utility_regret']<=float(decision['maximum_P201_mean_frozen_LCB_floor_Lagrangian_group_utility_regret'])};verdict=c['verdict_on_pass'] if all(checks.values()) else c['verdict_on_failure'];torch.save({'model_state_dict':student.state_dict(),'width':m['width'],'rate_knot_count':m['rate_knot_count'],'base_model':c['frozen_p285']},d/c['model_artifact']);summary_out={'schema_version':c['output_schema_version'],'task_id':c['task_id'],'hypothesis_id':c['hypothesis_id'],'status':'done','verdict':verdict,'role':c['role'],'training':{'group_count':int((~dev).sum()),'group_size':size,'final_normalized_log_price_mae':last},'source_development':source,'P201_post_hoc_development':r201,'decision_checks':checks,'resources':{'gpu':torch.cuda.get_device_name(0),'peak_gpu_memory_gib':torch.cuda.max_memory_allocated()/2**30,'peak_rss_gib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/2**20,'wall_seconds':time.monotonic()-started},'claim_boundary':c['claim_boundary']};(d/'summary.json').write_text(json.dumps(summary_out,indent=2)+'\n');(d/'status.json').write_text(json.dumps({'status':'done','completed_at_utc':datetime.now(timezone.utc).isoformat()},indent=2)+'\n');print(json.dumps({'run_dir':str(d),**summary_out},indent=2))


if __name__=='__main__':main()
